package controllers

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/prest/prest/v2/config"
)

var (
	ErrUserNotFound = errors.New(unf)
	jsonErrorMsg    = `{"error":"%s"}`
)

const (
	unf = "user not found"
)

func jsonError(writer http.ResponseWriter, message string, status int) {
	// If not in debug mode, sanitize error messages to avoid exposing sensitive information
	if !config.PrestConf.Debug {
		// Check if it's a database-related error and sanitize it
		if isDatabaseError(message) {
			message = "database error occurred"
		}
	}
	http.Error(writer, fmt.Sprintf(jsonErrorMsg, message), status)
}

// isDatabaseError checks if an error message is related to database operations
func isDatabaseError(message string) bool {
	// Common database error indicators
	dbErrorIndicators := []string{
		"pq:",
		"database",
		"relation",
		"table",
		"column",
		"syntax",
		"connection",
	}

	for _, indicator := range dbErrorIndicators {
		if containsIgnoreCase(message, indicator) {
			return true
		}
	}
	return false
}

// containsIgnoreCase checks if a string contains a substring (case insensitive)
func containsIgnoreCase(s, substr string) bool {
	return len(s) >= len(substr) && 
		(len(s) == len(substr) && 
			stringsEqualFold(s, substr) || 
			stringsContainsFold(s, substr))
}

// stringsEqualFold is a simplified version of strings.EqualFold for our use case
func stringsEqualFold(s, t string) bool {
	if len(s) != len(t) {
		return false
	}
	for i := 0; i < len(s); i++ {
		if lowerASCII(s[i]) != lowerASCII(t[i]) {
			return false
		}
	}
	return true
}

// stringsContainsFold is a simplified version of strings.Contains with case insensitivity
func stringsContainsFold(s, substr string) bool {
	if len(substr) == 0 {
		return true
	}
	if len(s) < len(substr) {
		return false
	}
	for i := 0; i <= len(s)-len(substr); i++ {
		if stringsEqualFold(s[i:i+len(substr)], substr) {
			return true
		}
	}
	return false
}

// lowerASCII returns the lowercase ASCII character
func lowerASCII(b byte) byte {
	if 'A' <= b && b <= 'Z' {
		return b + ('a' - 'A')
	}
	return b
}
EOF
```

